/**
 * Footer pointing AI agents and tools at the machine-readable versions of
 * the page (generated by `npm run tokens`).
 */
export function agentLinks(files: { label: string; href: string; note: string }[]): HTMLElement {
  const footer = document.createElement("p");
  footer.className = "agent-links text-body-medium";
  footer.append("For AI agents and tools: ");
  files.forEach((file, i) => {
    if (i) footer.append(" · ");
    const link = document.createElement("a");
    link.href = file.href;
    link.textContent = file.label;
    footer.append(link, ` (${file.note})`);
  });
  footer.append(" · ");
  const llms = document.createElement("a");
  llms.href = "/llms.txt";
  llms.textContent = "llms.txt";
  footer.append(llms);
  return footer;
}

export const COLOR_TOKENS_FILE = {
  label: "colors.json",
  href: "/tokens/colors.json",
  note: "design tokens with light/dark values and usage rules",
};

export const TYPOGRAPHY_TOKENS_FILE = {
  label: "typography.json",
  href: "/tokens/typography.json",
  note: "design tokens with usage rules",
};
